<?php

declare(strict_types=1);

namespace Domain\Helpers\Calls;

use App\AgentRequests\Contracts\CallSender;
use App\AgentRequests\Support\CallKey;
use Domain\Helpers\Http\Data\HelperJobNamed;
use Domain\Helpers\Http\Data\HelperNoticeListData;
use Domain\Helpers\Http\Data\HelperReceiptData;
use Domain\Helpers\Http\Data\HelperSteerData;

/**
 * The signed calls of Helpers, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class HelperCalls
{
    public function __construct(private CallSender $sender) {}

    public function cancelHelperJob(
        string $jobId,
        CallKey $requestKey = new CallKey(),
    ): HelperJobNamed {
        return $this->sender->send(CancelHelperJobCall::from([
            'jobId' => $jobId,
            'requestKey' => $requestKey,
        ]));
    }

    public function continueHelper(
        string $identityId,
        string $jobId,
        string $model,
        string|null $programKey,
        CallKey $requestKey = new CallKey(),
    ): HelperReceiptData {
        return $this->sender->send(ContinueHelperCall::from([
            'identityId' => $identityId,
            'jobId' => $jobId,
            'model' => $model,
            'programKey' => $programKey,
            'requestKey' => $requestKey,
        ]));
    }

    public function listHelperNotices(
    ): HelperNoticeListData {
        return $this->sender->send(ListHelperNoticesCall::from([
        ]));
    }

    /**
     * @param  list<string>  $sourceSubjects
     */
    public function sendHelper(
        string $identityId,
        string $profileKey,
        string $model,
        string|null $programKey,
        string|null $subject,
        string|null $purposeId,
        string|null $purposeText,
        string $brief,
        CallKey $requestKey = new CallKey(),
        array $sourceSubjects = [],
        bool $independent = false,
    ): HelperReceiptData {
        return $this->sender->send(SendHelperCall::from([
            'identityId' => $identityId,
            'profileKey' => $profileKey,
            'model' => $model,
            'programKey' => $programKey,
            'subject' => $subject,
            'purposeId' => $purposeId,
            'purposeText' => $purposeText,
            'brief' => $brief,
            'requestKey' => $requestKey,
            'sourceSubjects' => $sourceSubjects,
            'independent' => $independent,
        ]));
    }

    /**
     * @param  list<string>  $sourceSubjects
     */
    public function startHelper(
        string $profileKey,
        string $model,
        string|null $programKey,
        string|null $subject,
        string|null $purposeId,
        string|null $purposeText,
        string $brief,
        CallKey $requestKey = new CallKey(),
        array $sourceSubjects = [],
        bool $independent = false,
    ): HelperReceiptData {
        return $this->sender->send(StartHelperCall::from([
            'profileKey' => $profileKey,
            'model' => $model,
            'programKey' => $programKey,
            'subject' => $subject,
            'purposeId' => $purposeId,
            'purposeText' => $purposeText,
            'brief' => $brief,
            'requestKey' => $requestKey,
            'sourceSubjects' => $sourceSubjects,
            'independent' => $independent,
        ]));
    }

    public function steerHelper(
        string $identityId,
        string $text,
        CallKey $requestKey = new CallKey(),
    ): HelperSteerData {
        return $this->sender->send(SteerHelperCall::from([
            'identityId' => $identityId,
            'text' => $text,
            'requestKey' => $requestKey,
        ]));
    }
}
